      <button class="form-submit" onclick="this.textContent='⟳ מתחבר...';setTimeout(()=>this.textContent='כניסה ←',1500)">כניסה ←</button>
      <div style="text-align:center;margin-top:16px;font-size:13px;color:var(--gray-400)">
        עדיין לא מנויים? <button onclick="closeModal('modal-login');openRegister()" style="background:none;border:none;color:var(--blue);font-weight:700;cursor:pointer;font-family:Heebo,sans-serif;font-size:13px">הרשמו עכשיו</button>
      </div>
    </div>
  </div>
</div>

<script>
// Navigation
function showPage(id) {
  document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
  const el = document.getElementById('page-' + id);
  if (el) { el.classList.add('active'); el.classList.add('fade-in'); }
  document.querySelectorAll('[id^="nav-"]').forEach(b => b.classList.remove('active'));
  const nb = document.getElementById('nav-' + id);
  if (nb) nb.classList.add('active');
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

// Modal
function openModal(id) { document.getElementById(id).classList.remove('hidden'); document.body.style.overflow = 'hidden'; }
function closeModal(id) { document.getElementById(id).classList.add('hidden'); document.body.style.overflow = ''; }

function openLogin() { openModal('modal-login'); }
function openDemo() {
  var s = document.getElementById('demo-success');
  var b = document.getElementById('demo-submit-btn');
  if(s) s.classList.add('hidden');
  if(b) b.style.display = '';
  openModal('modal-demo');
}
function submitDemo() {
  var name = document.getElementById('demo-name').value.trim();
  var phone = document.getElementById('demo-phone').value.trim();
  var org = document.getElementById('demo-org').value.trim();
  if (!name || !phone || !org) { alert('נא למלא שם, שם הרשות ומספר טלפון'); return; }
  document.getElementById('demo-success').classList.remove('hidden');
  document.getElementById('demo-submit-btn').style.display = 'none';
}
function openRegister() {
  if (plan) selectPlan(plan);
  goStep(1);
  document.getElementById('reg-success').classList.add('hidden');
  document.getElementById('reg-step3').querySelector('.btn-next').style.display = '';
  openModal('modal-register');
}

// Steps
let currentStep = 1;
const stepTitles = { 1: 'הרשמה — פרטי הרשות', 2: 'הרשמה — בחירת מסלול', 3: 'הרשמה — פרטי תשלום' };
function goStep(n) {
  currentStep = n;
  document.querySelectorAll('.reg-step').forEach(s => s.classList.remove('active'));
  document.getElementById('reg-step' + n).classList.add('active');
  document.getElementById('modal-step-title').textContent = stepTitles[n];
  updateProgress(n);
  document.querySelector('.modal-box').scrollTop = 0;
}
function updateProgress(step) {
  [1,2,3].forEach(i => {
    const num = document.getElementById('pn'+i);
    const lbl = document.getElementById('pl'+i);
    if (i < step) { num.className = 'prog-num done'; num.textContent = '✓'; lbl.className = 'prog-label done'; }
    else if (i === step) { num.className = 'prog-num current'; num.textContent = i; lbl.className = 'prog-label current'; }
    else { num.className = 'prog-num todo'; num.textContent = i; lbl.className = 'prog-label todo'; }
    if (i < 3) { const line = document.getElementById('pline'+i); line.className = i < step ? 'prog-line done' : 'prog-line'; }
  });
}

// Plan selection
let selectedPlan = 'advanced';
const planData = {
  basic:    { name:'מנוי מלא — PrimeOS', total:'תיאום מול נציג', monthly:'' },
  advanced: { name:'מנוי מלא — PrimeOS', total:'תיאום מול נציג', monthly:'' },
  premium:  { name:'מנוי מלא — PrimeOS', total:'תיאום מול נציג', monthly:'' }
};
function selectPlan(plan) {
  selectedPlan = plan;
  ['basic','advanced','premium'].forEach(p => {
    const opt = document.getElementById('po-'+p);
    const rad = document.getElementById('pr-'+p);
    if (p === plan) {
      opt.classList.add('selected');
      rad.style.borderColor = 'var(--blue)'; rad.style.background = 'var(--blue)';
      rad.innerHTML = '<span style="display:block;width:8px;height:8px;border-radius:50%;background:#fff;margin:auto"></span>';
    } else {
      opt.classList.remove('selected');
      rad.style.borderColor = ''; rad.style.background = '';
      rad.innerHTML = '';
    }
  });
  const d = planData[plan];
  document.getElementById('sum-plan').textContent = d.name;
  document.getElementById('sum-total').textContent = d.total;
  document.getElementById('sum-monthly').textContent = d.monthly;
}

function completeRegistration() {
  document.getElementById('reg-step3').querySelector('.btn-next').style.display = 'none';
  document.getElementById('reg-step3').querySelector('.btn-back').style.display = 'none';
  document.getElementById('reg-success').classList.remove('hidden');
}

// Credit card formatting
document.addEventListener('DOMContentLoaded', () => {
  const cc = document.getElementById('f-card');
  if (cc) cc.addEventListener('input', e => {
    e.target.value = e.target.value.replace(/\D/g,'').replace(/(\d{4})/g,'$1 ').trim().slice(0,19);
  });
});
</script>

<!-- DEMO MODAL -->
<div id="modal-demo" class="modal-overlay hidden">
  <div class="login-box" style="max-width:480px">
    <div class="login-header" style="background:var(--navy)">
      <div class="login-title">תיאום הדגמה</div>
      <button class="modal-close" onclick="closeModal('modal-demo')">✕</button>
    </div>
    <div class="login-body">
      <div style="text-align:center;margin-bottom:22px">
        <div style="font-size:34px;margin-bottom:8px">🎯</div>
        <div style="font-size:16px;font-weight:700;color:var(--navy);margin-bottom:6px">30 דקות שישנו את הדוברות שלכם</div>
        <div style="font-size:13px;color:var(--gray-600);line-height:1.65">השאירו פרטים ונציג מטעמנו יחזור אליכם — ראו את המערכת בפעולה עם המיתוג שלכם.</div>
      </div>
      <div class="reg-group"><label class="reg-label">שם מלא <span style="color:#EF4444">*</span></label><input type="text" class="reg-input" id="demo-name" placeholder="שם פרטי ומשפחה"></div>
      <div class="reg-group"><label class="reg-label">שם הרשות / הארגון <span style="color:#EF4444">*</span></label><input type="text" class="reg-input" id="demo-org" placeholder="לדוגמה: עיריית פתח תקווה"></div>
      <div class="reg-group"><label class="reg-label">תפקיד</label><input type="text" class="reg-input" id="demo-role" placeholder="דובר, מנהל תקשורת, ראש רשות..."></div>
      <div class="reg-group"><label class="reg-label">מספר טלפון ישיר <span style="color:#EF4444">*</span></label><input type="tel" class="reg-input" id="demo-phone" placeholder="05X-XXXXXXX"></div>
      <div class="reg-group"><label class="reg-label">מייל (אופציונלי)</label><input type="email" class="reg-input" id="demo-email" placeholder="your@city.org.il"></div>
      <button id="demo-submit-btn" style="width:100%;background:var(--grad);color:#fff;border:none;border-radius:10px;padding:13px;font-size:15px;font-weight:700;cursor:pointer;font-family:Heebo,sans-serif;margin-top:6px" onclick="submitDemo()">שלח — ניצור קשר בהקדם ←</button>
      <div id="demo-success" class="hidden" style="text-align:center;margin-top:14px;background:#DCFCE7;border-radius:10px;padding:18px">
        <div style="font-size:26px;margin-bottom:6px">✅</div>
        <div style="font-size:15px;font-weight:700;color:#166534">הפרטים התקבלו!</div>
        <div style="font-size:13px;color:#16A34A;margin-top:4px">נציג יחזור אליכם תוך 24 שעות לתיאום הדגמה</div>
      </div>
      <div style="border-top:1px solid var(--gray-100);margin-top:20px;padding-top:16px;text-align:center">
        <div style="font-size:12px;color:var(--gray-400);margin-bottom:8px">או התקשרו ישירות:</div>
        <a href="tel:0549020253" style="font-size:18px;font-weight:800;color:var(--navy);text-decoration:none;display:flex;align-items:center;justify-content:center;gap:8px">📞 054-902-0253 <span style="font-size:13px;font-weight:500;color:var(--gray-400)">מאור — א׳–ה׳</span></a>
      </div>
    </div>
  </div>
</div>

</body>